// 八张手绘线稿：AI 按截图风格重绘，不是 Top Widgets 原图。
// 以 base64 内嵌，透明底、黑色线条、白色填充；小组件里不依赖外部文件。

declare const UIImage: { fromBase64String(value: string): UIImage | null } | undefined;

export type ArtKey = "mon" | "tue" | "wed" | "thu" | "fri" | "weekend" | "holiday" | "makeup";

const DATA: Record<ArtKey, string> = {
  mon: "",
  tue: "",
  wed: "",
  thu: "",
  fri: "",
  weekend: "",
  holiday: "",
  makeup: "",
};

const cache: Partial<Record<ArtKey, UIImage | null>> = {};

/** 解一张图；没有 UIImage 的环境返回 null，由调用方退化成符号。 */
export function artFor(key: ArtKey): UIImage | null {
  if (cache[key] !== undefined) return cache[key] ?? null;
  let image: UIImage | null = null;
  if (typeof UIImage !== "undefined") {
    try { image = UIImage.fromBase64String(DATA[key]); } catch { image = null; }
  }
  cache[key] = image;
  return image;
}
